ALTER TABLE search_raw_files ADD CONSTRAINT search_raw_files_pkey PRIMARY KEY (search_id, raw_path);

-- views / materialized views, in dependency order (refresh after first ingest)
CREATE MATERIALIZED VIEW IF NOT EXISTS delimp_mv_corpus_stats AS
 SELECT ( SELECT count(DISTINCT delimp_precursors.stripped_seq) AS count
           FROM delimp_precursors
          WHERE delimp_precursors.stripped_seq IS NOT NULL AND delimp_precursors.stripped_seq <> ''::text) AS distinct_peptides,
    ( SELECT count(DISTINCT delimp_proteins.protein_group) AS count
           FROM delimp_proteins
          WHERE delimp_proteins.protein_group IS NOT NULL AND delimp_proteins.protein_group <> ''::text) AS distinct_protein_groups,
    ( SELECT count(*) AS count
           FROM delimp_precursors) AS total_precursors,
    ( SELECT count(*) AS count
           FROM delimp_proteins) AS total_proteins,
    ( SELECT count(*) AS count
           FROM delimp_precursors
          WHERE delimp_precursors.im IS NOT NULL) AS im_bearing_precursors,
    ( SELECT count(DISTINCT raw_files.raw_basename) AS count
           FROM raw_files
          WHERE raw_files.raw_basename IS NOT NULL AND raw_files.raw_basename <> ''::text) AS distinct_acquisitions,
    ( SELECT count(*) AS count
           FROM raw_files) AS raw_file_rows,
    CURRENT_TIMESTAMP AS computed_at WITH NO DATA;

CREATE MATERIALIZED VIEW IF NOT EXISTS delimp_mv_im_scatter AS
 SELECT rt,
    irt,
    im,
    charge,
    precursor_mz,
    intensity_log2
   FROM ( SELECT DISTINCT ON (delimp_precursors.stripped_seq, delimp_precursors.charge) delimp_precursors.stripped_seq,
            delimp_precursors.charge,
            delimp_precursors.rt,
            delimp_precursors.irt,
            delimp_precursors.im,
            delimp_precursors.precursor_mz,
            delimp_precursors.intensity_log2
           FROM delimp_precursors
          WHERE delimp_precursors.im > 0.3::double precision AND delimp_precursors.rt IS NOT NULL AND (delimp_precursors.irt IS NULL OR delimp_precursors.irt > '-100'::integer::double precision AND delimp_precursors.irt < 300::double precision)
          ORDER BY delimp_precursors.stripped_seq, delimp_precursors.charge) q
 LIMIT 20000 WITH NO DATA;

CREATE MATERIALIZED VIEW IF NOT EXISTS delimp_mv_species_proteins AS
 SELECT m.organism_name,
    p.protein_group,
    max(p.gene) AS gene,
    count(DISTINCT p.raw_path) AS n_runs,
    count(DISTINCT p.search_id) AS n_searches,
    sum(p.n_precursors) AS sum_prec,
    max(p.n_unique_peptides) AS max_pep,
    avg(NULLIF(p.intensity, 0::double precision)) AS mean_int,
    bool_or(p.is_contaminant) AS contam
   FROM delimp_proteins p
     JOIN delimp_sample_metadata m ON m.raw_path = p.raw_path
  WHERE m.organism_name IS NOT NULL AND m.organism_name <> ''::text AND p.protein_group IS NOT NULL AND p.protein_group <> ''::text
  GROUP BY m.organism_name, p.protein_group WITH NO DATA;

CREATE MATERIALIZED VIEW IF NOT EXISTS delimp_mv_top_genes AS
 SELECT gene,
    count(DISTINCT protein_group) AS n_groups,
    count(DISTINCT search_id) AS n_searches,
    count(DISTINCT raw_path) AS n_runs
   FROM delimp_proteins
  WHERE gene IS NOT NULL AND gene <> ''::text
  GROUP BY gene
  ORDER BY (count(DISTINCT raw_path)) DESC, (count(DISTINCT search_id)) DESC
 LIMIT 5000 WITH NO DATA;

CREATE MATERIALIZED VIEW IF NOT EXISTS delimp_mv_top_peptides AS
 SELECT stripped_seq,
    count(*) AS n_obs,
    count(DISTINCT raw_path) AS n_runs,
    count(DISTINCT search_id) AS n_searches,
    count(DISTINCT charge) AS n_charges,
    bool_or(im IS NOT NULL) AS has_im
   FROM delimp_precursors
  GROUP BY stripped_seq
  ORDER BY (count(DISTINCT raw_path)) DESC, (count(*)) DESC
 LIMIT 100000 WITH NO DATA;

CREATE MATERIALIZED VIEW IF NOT EXISTS delimp_mv_top_proteins AS
 SELECT protein_group,
    max(gene) AS gene,
    count(DISTINCT search_id) AS n_searches,
    count(DISTINCT raw_path) AS n_runs,
    sum(n_precursors) AS sum_precursors,
    bool_or(is_contaminant) AS any_contaminant
   FROM delimp_proteins
  GROUP BY protein_group
  ORDER BY (count(DISTINCT raw_path)) DESC, (sum(n_precursors)) DESC NULLS LAST
 LIMIT 5000 WITH NO DATA;

CREATE OR REPLACE VIEW aaa_fran_read_me_first AS
 SELECT n,
    topic,
    rule
   FROM ( VALUES (1,'vendor / file format'::text,'NEVER infer vendor from raw_path. Its extension was GUESSED from platform at ingest and 5,629 rows are stale. Use hive_path, platform, instrument_model, or instrument_serial (Thermo MA10354C/fsn20215 vs Bruker 1854399.00153).'::text), (2,'identifying a search'::text,'search_name is NOT a key: 1,963 searches, 1,927 names. ILIKE matching spans unrelated projects on different instruments. Carry delimp_searches.id through every follow-up query. One legitimate search CAN span two instrument models, so a vendor split inside a search is not itself a bug.'::text), (3,'never compare across rows'::text,'Before concluding two fields contradict each other, confirm they came from the SAME row. Comparing a model from one search against a file extension from another has already produced a false bug report. This is the single most common error made against this corpus.'::text), (4,'counting'::text,'raw_files has 19,874 rows but 11,671 distinct raw_basename; the basename is the acquisition. delimp_proteins.n_unique_peptides is PER-RUN -- SUMming it overstated a peptide count by up to 56x. Use COUNT(DISTINCT stripped_seq) FROM delimp_precursors.'::text), (5,'contaminants'::text,'is_contaminant marks WHICH FASTA the match came from, not what the molecule is. The same gene is flagged both ways (ALB 12,279 / 14,125). Filtering on it deletes casein from milk and keratin from skin -- the analyte. Use it as a feature, not a filter.'::text), (6,'absent means unrecorded'::text,'organism_taxon_id (70.7%) was a hand-typed CLI flag; absence means nobody typed it, not unknown species. best_q_value is ~99.9% NULL so ORDER BY on it returns an arbitrary row. sample_type is the constant ''study_sample''.'::text), (7,'experimental design'::text,'tissue/disease/cell_line/biological_replicate/sdrf_row_json are 0% populated corpus-wide. Experimental groups DO exist upstream in the Spectronaut reports as R_Condition / R_Replicate but have never been ingested. Do not conclude from an empty column that the information does not exist.'::text), (8,'meaning changes'::text,'delimp_searches.n_proteins_total changed 2026-07-27 from a protein GROUP count to a true protein count (4.75M -> 6.00M). Any protein figure quoted from before that date is a group count. Check COMMENT ON COLUMN before trusting a historical number.'::text), (9,'stale objects'::text,'delimp_spectrum_regen_queue is abandoned (~1,871 meaningless rows); the spectrum lane truth is delimp_spectrum_lane. delimp_precursor_xic.search_id is TEXT and 13 of 23 values are name-slugs, so it does NOT join to delimp_searches.id.'::text), (10,'full detail'::text,'Every column above carries a COMMENT with the specifics. Read them with: SELECT c.relname, a.attname, col_description(c.oid, a.attnum) FROM pg_class c JOIN pg_attribute a ON a.attrelid=c.oid WHERE a.attnum>0 AND col_description(c.oid, a.attnum) IS NOT NULL ORDER BY 1,2;'::text)) t(n, topic, rule);

CREATE OR REPLACE VIEW delimp_training_gold AS
 WITH run_q AS (
         SELECT delimp_precursors.raw_path,
            count(*) AS n_conf
           FROM delimp_precursors
          WHERE delimp_precursors.q_value <= 0.01::double precision AND delimp_precursors.superseded_by IS NULL
          GROUP BY delimp_precursors.raw_path
        )
 SELECT p.id,
    p.search_id,
    p.raw_path,
    rf.raw_basename AS sample_id,
    rf.instrument_model,
    rf.platform,
    rf.acquisition_method,
    sm.organism_name,
    sm.predicted_organism_name,
    sm.predicted_organism_confidence,
    p.stripped_seq,
    char_length(p.stripped_seq) AS pep_length,
    p.modified_seq_proforma,
    p.mods,
    p.n_mods,
    p.charge,
    p.precursor_mz,
    p.rt,
    p.irt,
    p.im,
    p.iim,
    p.q_value,
    p.global_q_value,
    p.pep,
    p.site_localization_probability,
    p.n_engines_confirming,
    p.intensity,
    p.intensity_log2,
    p.ms2_spectrum_md5,
    p.n_peaks_total,
    p.peak_snr
   FROM delimp_precursors p
     JOIN run_q rq ON rq.raw_path = p.raw_path AND rq.n_conf >= 100
     LEFT JOIN raw_files rf ON rf.raw_path = p.raw_path
     LEFT JOIN delimp_sample_metadata sm ON sm.raw_path = p.raw_path
  WHERE p.q_value <= 0.01::double precision AND p.superseded_by IS NULL AND p.stripped_seq ~ '^[ACDEFGHIKLMNPQRSTVWY]+$'::text AND char_length(p.stripped_seq) >= 7 AND char_length(p.stripped_seq) <= 30 AND p.charge >= 1 AND p.charge <= 6 AND (COALESCE(p.n_mods, 0) = 0 OR COALESCE(p.site_localization_probability, 1::real) > 0.75::double precision) AND COALESCE(rf.raw_basename, ''::text) !~* '(blank|wash|carryover|column.?wash|(^|[_-])qc([_-]|$))'::text;

CREATE MATERIALIZED VIEW IF NOT EXISTS delimp_mv_protein_agg AS
 SELECT protein_group,
    max(gene) AS gene,
    count(DISTINCT organism_name) AS n_species,
    sum(n_runs) AS sum_runs,
    sum(n_searches) AS sum_searches,
    max(max_pep) AS max_pep,
    max(mean_int) AS peak_mean_int,
    bool_or(contam) AS contam,
    bool_or(contam) OR protein_group ~* '^(crap|cont[_-])'::text AS is_cont,
    (array_agg(organism_name ORDER BY n_runs DESC))[1] AS top_organism
   FROM delimp_mv_species_proteins
  GROUP BY protein_group WITH NO DATA;

