-- seed: delimp_precursors.ingested_schema_version references this table, so the
-- first ingest FAILS on an empty one. Keep in step with ingest/versions.py.
INSERT INTO delimp_schema_version (version) VALUES ('1.0.0') ON CONFLICT DO NOTHING;

-- REFRESH ORDER (matviews depend on each other; refreshing out of order fails
-- with 'materialized view has not been populated'). After your first ingest:
--   REFRESH MATERIALIZED VIEW delimp_mv_corpus_stats;
--   REFRESH MATERIALIZED VIEW delimp_mv_im_scatter;
--   REFRESH MATERIALIZED VIEW delimp_mv_species_proteins;
--   REFRESH MATERIALIZED VIEW delimp_mv_top_genes;
--   REFRESH MATERIALIZED VIEW delimp_mv_top_peptides;
--   REFRESH MATERIALIZED VIEW delimp_mv_top_proteins;
--   REFRESH MATERIALIZED VIEW delimp_mv_protein_agg;
